CREATE DATABASE customer_behaviour;
SHOW DATABASES;
USE customer_behaviour;
SELECT * FROM customer LIMIT 10;

-- Q1. Select the total revenue generated by male vs female customers?

select gender, sum(purchase_amount) as revenuue
from customer
group by gender;

-- Q2. Which customer used a discount but still spent more than
-- the average purchase amount

select customer_id, discount_applied
from customer
where discount_applied = 'Yes' 
and 
purchase_amount >= (select avg(purchase_amount) from customer);

-- Q3. which are the top 5 products with the highest average 
-- review rating

select item_purchased, 
round(avg(review_rating), 2)as top_review_rating
from customer 
group by item_purchased
order by top_review_rating desc
limit 5;

-- Q4.Compare the average Purchase Amounts between Standard and 
-- Express shipping

select shipping_type, round((purchase_amount),2) 
as avg_shipping_amount
from customer
where shipping_type in ('Express' ,'Standard')
group by shipping_type;

-- Qs.5 Do subscribed customers spend more? Compare average spend
-- and total revenue between subscribers and non-subsribers

select subscription_status , 
count(customer_id) as total_customer,
round(sum(purchase_amount),2) as total_spend,
round(avg(purchase_amount),2) as avg_revenue
from customer
group by subscription_status;

-- Q6. Which 5 products have the highest percentage of purchases 
-- with discounts applied 

SELECT
    item_purchased,
    ROUND(
        SUM(CASE
            WHEN discount_applied = 'Yes' THEN 1
            ELSE 0
        END) * 100.0 / COUNT(*),
        2
    ) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;

-- Q7. Segnment customers based on New, returning, and Loyal based on their 
-- total number of previous purchases and show the count of each 
-- segment 

with customer_type as (
select customer_id, previous_purchases,
CASE 
    WHEN previous_purchases =1 THEN 'New'
    WHEN previous_purchases BETWEEn 2 and 10 THEN 'Returnning'
    ELSE 'Loyal'
	END AS customer_segment
from customer
)
select customer_segment , count(*) as "Number_of_customers"
from customer_type
group by customer_segment;

-- Q8 . What are the top 3 most purchased products by category
WITH item_counts AS (
    SELECT
        category,
        item_purchased,
        COUNT(customer_id) AS total_orders,
        ROW_NUMBER() OVER (
            PARTITION BY category
            ORDER BY COUNT(customer_id) DESC
        ) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)
SELECT
    category,
    item_purchased,
    total_orders,
    item_rank
FROM item_counts;
-- Q.9 Are customers who are repeat buyers (more than 5 previous 
-- purchases also likely to subscribe

select subscription_status,
count(customer_id) as repeat_buyers
from customer
where previous_purchases > 5
group by subscription_status;

-- Q.6 What is the revenue contribution of each age group?

select age_group , 
sum(purchase_amount) as total_revenue 
from customer
group by age_group
order by total_revenue desc;








 


